<?php
require __DIR__.'/config/database.php';require __DIR__.'/includes/functions.php';require_admin();verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){require_admin();$action=$_POST['action']??'';if($action==='save'){$nis=(int)($_POST['nis']??0);$nama=trim($_POST['nama']??'');$kelas=trim($_POST['kelas']??'');if(!$nis||!$nama||!$kelas){flash('NIS, nama, dan kelas wajib diisi.','error');}else{try{$st=$pdo->prepare('INSERT INTO siswa(nis,nama,kelas) VALUES(?,?,?) ON DUPLICATE KEY UPDATE nama=VALUES(nama),kelas=VALUES(kelas)');$st->execute([$nis,$nama,$kelas]);flash('Data siswa disimpan.');}catch(Throwable $e){flash('Data siswa gagal disimpan.','error');}}header('Location: siswa.php');exit;}if($action==='delete'){$st=$pdo->prepare('DELETE FROM siswa WHERE nis=?');$st->execute([(int)$_POST['nis']]);flash('Data siswa dihapus.');header('Location: siswa.php');exit;}}
$pageTitle='Data Siswa';$rows=$pdo->query('SELECT s.*,COUNT(c.id_checklist) total_checklist FROM siswa s LEFT JOIN checklist c ON c.nis=s.nis GROUP BY s.nis ORDER BY s.kelas,s.nama')->fetchAll();require __DIR__.'/includes/header.php';
?><div class="welcome-row"><div><span class="eyebrow">KOMUNITAS SEKOLAH</span><h1>Data Siswa</h1><p>Data siswa yang terhubung dengan aktivitas checklist energi.</p></div></div><div class="content-split"><section class="panel form-panel"><div class="panel-heading"><div><h2>Tambah / Perbarui Siswa</h2><p>Jika NIS sudah ada, data akan diperbarui.</p></div></div><?php if(is_admin()): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><div class="form-field"><label>NIS</label><input class="form-control" type="number" min="1" name="nis" required placeholder="Contoh: 6"></div><div class="form-field"><label>Nama lengkap</label><input class="form-control" name="nama" required placeholder="Nama siswa"></div><div class="form-field"><label>Kelas</label><input class="form-control" name="kelas" required placeholder="Contoh: XI RPL 1"></div><button class="btn btn-primary btn-full">Simpan Data Siswa</button></form><?php else: ?><div class="empty-state"><span>♙</span><b>Mode lihat data</b><p>Hanya Admin yang dapat menambah atau menghapus data siswa.</p></div><?php endif; ?></section><section class="panel table-panel"><div class="panel-heading"><div><h2>Daftar siswa</h2><p><?= count($rows) ?> siswa terdaftar.</p></div></div><div class="table-wrap"><table><thead><tr><th>Siswa</th><th>NIS</th><th>Kelas</th><th>Checklist</th><?php if(is_admin()): ?><th>Aksi</th><?php endif; ?></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><div class="table-person"><span class="avatar avatar-small"><?= e(strtoupper(substr($r['nama'],0,1))) ?></span><b><?= e($r['nama']) ?></b></div></td><td><?= (int)$r['nis'] ?></td><td><span class="status-pill"><?= e($r['kelas']) ?></span></td><td><?= (int)$r['total_checklist'] ?></td><?php if(is_admin()): ?><td><form method="post" onsubmit="return confirm('Hapus siswa ini? Checklist siswa terkait juga akan terhapus.')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="nis" value="<?= (int)$r['nis'] ?>"><button class="btn btn-danger btn-sm">Hapus</button></form></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div></section></div><?php require __DIR__.'/includes/footer.php'; ?>
